import type { VendorQuoteAdapterInput } from "../types.js";
import {
  providerDispatchAuthorizationDenial,
  type ProviderDispatchAuthorizationDenial,
} from "./providerDispatchAuthorization.js";

/**
 * Generated by `npm run fixture:onboard -- geomiq --stage=live` (OVD-687).
 *
 * Adapter-side binding for production Geomiq launches: the shared
 * provider check (`providerDispatchAuthorization.ts`) bound to the
 * Geomiq envelope identity. The identity is NOT reviewed: it is absent
 * from `REVIEWED_PROVIDER_DISPATCH_ENVELOPES` and has no review row, so no
 * permit can name it. Declaring it here admits nothing.
 */
export const GEOMIQ_DISPATCH_ENVELOPE = Object.freeze({ id: "geomiq-quote-envelope", version: 1 });

export type GeomiqDispatchAuthorizationDenial = ProviderDispatchAuthorizationDenial;

export function geomiqDispatchAuthorizationDenial(
  input: VendorQuoteAdapterInput,
  nowMs: number = Date.now(),
): GeomiqDispatchAuthorizationDenial | null {
  return providerDispatchAuthorizationDenial(
    input,
    { provider: "geomiq", ...GEOMIQ_DISPATCH_ENVELOPE },
    nowMs,
  );
}
